import { sql } from 'drizzle-orm'
import { timestamp, uuid } from 'drizzle-orm/pg-core'

/**
 * Creates a UUID primary key generated by PostgreSQL 18's native uuidv7().
 * UUIDv7 is time-ordered; an identifier is still not proof of access or a secret.
 * Keep existing auth/provider IDs and their references in their original types.
 */
export const uuidv7PrimaryKey = () =>
  uuid('id')
    .default(sql`uuidv7()`)
    .primaryKey()

/** Records the creation instant with timezone support; defaults to database time. */
export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).defaultNow().notNull()

/**
 * Records the last modification instant; inserts default to database time.
 * Drizzle supplies the application server's current time on updates unless an
 * explicit value is supplied. Raw SQL and other writers must update it themselves;
 * $onUpdate does not create a PostgreSQL trigger or prevent explicit overrides.
 */
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull()

/** Returns fresh column builders for each table; do not reuse one object across tables. */
export const timestamps = () => ({
  createdAt: createdAt(),
  updatedAt: updatedAt(),
})
